// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    recorder rec;

    function setUp() public {
        c = new airPort();
        rec = new recorder();
    }

    function testFuzz_property(address from, uint256 v) public {
        address[] memory tos = new address[](1);
        tos[0] = address(0xdead);

        bool ok = c.transfer(from, address(rec), tos, v);
        assertTrue(ok);

        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bytes4 recorded = bytes4(rec.lastData());
        assertTrue(recorded == expected);
    }
}

contract recorder {
    bytes public lastData;

    fallback() external payable {
        lastData = msg.data;
    }
}
